CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'auditor', team_id TEXT, suspended INTEGER DEFAULT 0, failed_attempts INTEGER DEFAULT 0, locked_until TEXT, totp_secret TEXT, email_verified INTEGER DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS refresh_tokens (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT);
CREATE TABLE IF NOT EXISTS teams (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS team_members (team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(team_id,user_id));
CREATE TABLE IF NOT EXISTS roles (id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS permissions (id TEXT PRIMARY KEY, description TEXT);
CREATE TABLE IF NOT EXISTS role_permissions (role_id TEXT REFERENCES roles(id), permission_id TEXT REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS user_profiles (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, avatar_url TEXT, theme TEXT DEFAULT 'system', notification_prefs TEXT DEFAULT '{}');
CREATE TABLE IF NOT EXISTS invites (id TEXT PRIMARY KEY, email TEXT NOT NULL, team_id TEXT, role TEXT NOT NULL, token_hash TEXT NOT NULL, expires_at TEXT NOT NULL, accepted_at TEXT);
CREATE TABLE IF NOT EXISTS credentials (id TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL, username TEXT NOT NULL, encrypted_blob TEXT NOT NULL, owner_user_id TEXT REFERENCES users(id), visibility TEXT DEFAULT 'private', team_id TEXT, priority INTEGER DEFAULT 100, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS credential_assignments (credential_id TEXT REFERENCES credentials(id) ON DELETE CASCADE, node_id TEXT, node_group_id TEXT, PRIMARY KEY(credential_id,node_id,node_group_id));
CREATE TABLE IF NOT EXISTS nodes (id TEXT PRIMARY KEY, hostname TEXT NOT NULL, fqdn TEXT, ip TEXT, os_version TEXT, os_build TEXT, connection_mode TEXT DEFAULT 'agentless', transport TEXT, status TEXT DEFAULT 'unknown', failures INTEGER DEFAULT 0, firewall_state TEXT DEFAULT 'enforcing', last_seen_at TEXT, agent_id TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS node_groups (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS node_group_members (group_id TEXT REFERENCES node_groups(id) ON DELETE CASCADE, node_id TEXT REFERENCES nodes(id) ON DELETE CASCADE, PRIMARY KEY(group_id,node_id));
CREATE TABLE IF NOT EXISTS node_facts (node_id TEXT PRIMARY KEY REFERENCES nodes(id) ON DELETE CASCADE, snapshot_json TEXT NOT NULL, collected_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS dns_lookups (node_id TEXT PRIMARY KEY REFERENCES nodes(id) ON DELETE CASCADE, forward_result TEXT, reverse_result TEXT, mismatch INTEGER DEFAULT 0, checked_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS policies (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, owner_user_id TEXT, current_version_id TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS policy_versions (id TEXT PRIMARY KEY, policy_id TEXT NOT NULL REFERENCES policies(id) ON DELETE CASCADE, version_no INTEGER NOT NULL, graph_json TEXT NOT NULL, rules_compiled_json TEXT NOT NULL, created_by TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, comment TEXT, UNIQUE(policy_id,version_no));
CREATE TABLE IF NOT EXISTS policy_assignments (id TEXT PRIMARY KEY, policy_id TEXT REFERENCES policies(id) ON DELETE CASCADE, node_id TEXT, node_group_id TEXT, assigned_at TEXT DEFAULT CURRENT_TIMESTAMP, assigned_by TEXT);
CREATE TABLE IF NOT EXISTS policy_apply_runs (id TEXT PRIMARY KEY, policy_id TEXT, version_id TEXT, node_id TEXT, status TEXT NOT NULL, diff_json TEXT, started_at TEXT DEFAULT CURRENT_TIMESTAMP, finished_at TEXT, error TEXT);
CREATE TABLE IF NOT EXISTS verifier_runs (id TEXT PRIMARY KEY, status TEXT NOT NULL, started_at TEXT DEFAULT CURRENT_TIMESTAMP, finished_at TEXT, requested_by TEXT);
CREATE TABLE IF NOT EXISTS verifier_results (id TEXT PRIMARY KEY, run_id TEXT REFERENCES verifier_runs(id) ON DELETE CASCADE, node_id TEXT, policy_id TEXT, port INTEGER, proto TEXT, expected TEXT, actual TEXT, latency_ms INTEGER, passed INTEGER, run_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS identity_segments (id TEXT PRIMARY KEY, name TEXT NOT NULL, node_id TEXT, policy_id TEXT, port INTEGER NOT NULL, protocol TEXT DEFAULT 'TCP', account_sid TEXT, source_ip TEXT, extra_ports TEXT DEFAULT '[]', source_process TEXT, fallback_to_logged_on_user INTEGER DEFAULT 0, fail_open INTEGER DEFAULT 0, ttl_minutes INTEGER DEFAULT 240, mode TEXT DEFAULT 'agentless', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS logon_rights (id TEXT PRIMARY KEY, node_id TEXT NOT NULL, account_sid TEXT NOT NULL, logon_type TEXT NOT NULL, right_assignment TEXT NOT NULL, source TEXT, baseline INTEGER DEFAULT 0, created_by TEXT, at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS jit_grants (id TEXT PRIMARY KEY, segment_id TEXT, node_id TEXT, account_sid TEXT, src_ip TEXT, dst_port INTEGER, rule_path TEXT, grant_type TEXT, ttl_seconds INTEGER, granted_at TEXT DEFAULT CURRENT_TIMESTAMP, expires_at TEXT, revoked_at TEXT, mfa_challenge_id TEXT);
CREATE TABLE IF NOT EXISTS rpc_filter_rules (id TEXT PRIMARY KEY, node_id TEXT, interface_uuid TEXT, opnum INTEGER, source TEXT, action TEXT, audit INTEGER DEFAULT 1, label TEXT, applied_at TEXT);
CREATE TABLE IF NOT EXISTS mfa_challenges (id TEXT PRIMARY KEY, node_id TEXT, user_upn TEXT, segment_id TEXT, connection_5tuple TEXT, status TEXT, challenged_at TEXT DEFAULT CURRENT_TIMESTAMP, resolved_at TEXT, expires_at TEXT);
CREATE TABLE IF NOT EXISTS log_events (id TEXT PRIMARY KEY, node_id TEXT, record_id INTEGER, event_id INTEGER, action TEXT, protocol TEXT, src_ip TEXT, dst_ip TEXT, dst_port INTEGER, direction TEXT, program TEXT, account_sid TEXT, challenge_id TEXT, received_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(node_id,record_id));
CREATE TABLE IF NOT EXISTS learning_sessions (id TEXT PRIMARY KEY, node_id TEXT, started_at TEXT DEFAULT CURRENT_TIMESTAMP, ends_at TEXT, status TEXT, generated_policy_id TEXT);
CREATE TABLE IF NOT EXISTS agents (id TEXT PRIMARY KEY, node_id TEXT UNIQUE, cert_thumbprint TEXT, version TEXT, mode TEXT DEFAULT 'pull', last_checkin_at TEXT, revoked_at TEXT);
CREATE TABLE IF NOT EXISTS enrollment_tokens (id TEXT PRIMARY KEY, node_id TEXT, token_hash TEXT UNIQUE NOT NULL, expires_at TEXT, used_at TEXT);
CREATE TABLE IF NOT EXISTS agent_jobs (id TEXT PRIMARY KEY, agent_id TEXT, type TEXT, payload_json TEXT, status TEXT DEFAULT 'queued', created_at TEXT DEFAULT CURRENT_TIMESTAMP, finished_at TEXT);
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, actor_user_id TEXT, action TEXT, entity_type TEXT, entity_id TEXT, before_json TEXT, after_json TEXT, at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_logs_node_time ON log_events(node_id,received_at);
CREATE INDEX IF NOT EXISTS idx_apply_node ON policy_apply_runs(node_id,started_at);
CREATE INDEX IF NOT EXISTS idx_audit_time ON audit_log(at);
